"use strict";(globalThis.webpackChunkempora_for_woocommerce_docs=globalThis.webpackChunkempora_for_woocommerce_docs||[]).push([[2150],{82546(e){e.exports=JSON.parse('[{"title":"Free download from your dashboard, and corrected pages","description":"Free accounts can download the plugin from the dashboard, the tools moved to ZTools, and the home and pricing pages now match what the plugin does.","permalink":"/changelog/plugin-download-and-corrected-pages-2026-11-07","date":"2026-11-07","tags":[{"label":"release","permalink":"/changelog/tags/release"}]},{"title":"An update screen, and policies that match what Empora does","description":"Empora can now ask you to update when a fix matters. The Privacy and Cookie Policies were corrected against the code, and usage counting is now told once at the foot of your first visit.","permalink":"/changelog/update-screen-and-corrected-policies-2026-11-06","date":"2026-11-06","tags":[{"label":"release","permalink":"/changelog/tags/release"}]},{"title":"Page tours on Downloads, AI drafts and Referrals","description":"Downloads, AI drafts and Referrals now have their own page tour, so every page of your Empora account has one.","permalink":"/changelog/tours-on-downloads-ai-drafts-and-referrals-2026-10-29","date":"2026-10-29","tags":[{"label":"release","permalink":"/changelog/tags/release"}]},{"title":"Your Empora account, redesigned and built for your phone","description":"The Empora account has a new look on every page, and on a phone it now works like an app, with a bottom bar for Overview, Licences, Stores, AI drafts and More.","permalink":"/changelog/your-account-on-a-phone-2026-10-29","date":"2026-10-29","tags":[{"label":"release","permalink":"/changelog/tags/release"}]},{"title":"AI drafts in your Empora account","description":"A new AI drafts page writes a product description from your notes or answers how a module\'s settings work, with Speak for voice input.","permalink":"/changelog/ai-drafts-2026-10-28","date":"2026-10-28","tags":[{"label":"release","permalink":"/changelog/tags/release"}]},{"title":"Tour hints follow your account, and How Empora works from the home page","description":"The one-line tour offer now shows once for your account on every device, and the home page links straight to the How Empora works walkthrough.","permalink":"/changelog/tour-hints-follow-your-account-2026-10-28","date":"2026-10-28","tags":[{"label":"release","permalink":"/changelog/tags/release"}]},{"title":"Page tours in your account, and a How Empora works walkthrough","description":"Overview, License, Stores, Billing and Settings now have a page tour behind a map button in the header, and How Empora works shows six screens of the account one step at a time.","permalink":"/changelog/page-tours-and-how-empora-works-2026-10-27","date":"2026-10-27","tags":[{"label":"release","permalink":"/changelog/tags/release"}]},{"title":"Bundle contents, paying from a balance on the Checkout block, and overpaid orders","description":"The Bundles editor now builds a bundle\'s contents and where it is shown, customers can pay from store credit and wallet on the Checkout block, and an order edited to charge less can return the difference.","permalink":"/changelog/bundle-contents-and-checkout-balance-2026-10-26","date":"2026-10-26","tags":[{"label":"modules","permalink":"/changelog/tags/modules"},{"label":"release","permalink":"/changelog/tags/release"}]},{"title":"Documentation corrections \u2014 all 78 modules, and the new plan limits","description":"Three modules were documented as unavailable in 1.0 after they had already been enabled. That is corrected across the site, along with the free, Starter and Professional record limits.","permalink":"/changelog/documentation-corrections-2026-09-12","date":"2026-09-12","tags":[{"label":"documentation","permalink":"/changelog/tags/documentation"}]},{"title":"1.0.0 \u2014 in preparation","description":"Empora for WooCommerce 1.0.0 has not been released yet. What the first release contains, and what this changelog will carry once it ships.","permalink":"/changelog/1-0-0-in-preparation","date":"2026-08-29","tags":[{"label":"release","permalink":"/changelog/tags/release"}]}]')}}]);